#!/usr/bin/env python3
# Minimal AArch64 ELF64 disassembler helper (no binutils needed)
import struct, sys
from capstone import Cs, CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN

def parse_elf(path):
    with open(path, 'rb') as f:
        data = f.read()
    assert data[:4] == b'\x7fELF'
    is64 = data[4] == 2
    assert is64
    e_shoff = struct.unpack('<Q', data[0x28:0x30])[0]
    e_shentsize = struct.unpack('<H', data[0x3a:0x3c])[0]
    e_shnum = struct.unpack('<H', data[0x3c:0x3e])[0]
    e_shstrndx = struct.unpack('<H', data[0x3e:0x40])[0]
    sections = []
    for i in range(e_shnum):
        off = e_shoff + i * e_shentsize
        name, stype, flags, addr, offset, size, link, info = struct.unpack('<IIQQQQII', data[off:off+48])
        sections.append({'name_off': name, 'type': stype, 'flags': flags, 'addr': addr, 'offset': offset, 'size': size, 'link': link})
    shstr = sections[e_shstrndx]
    shstrtab = data[shstr['offset']:shstr['offset']+shstr['size']]
    def zstr(buf, off):
        end = buf.index(b'\x00', off)
        return buf[off:end].decode('utf-8', 'replace')
    for s in sections:
        s['name'] = zstr(shstrtab, s['name_off'])
    # symbols
    syms = {}
    for s in sections:
        if s['type'] in (2, 11):  # SYMTAB / DYNSYM
            symdata = data[s['offset']:s['offset']+s['size']]
            strsec = sections[s['link']]
            strtab = data[strsec['offset']:strsec['offset']+strsec['size']]
            entsz = 24
            for i in range(0, len(symdata) - entsz + 1, entsz):
                st_name, st_info, st_other, st_shndx, st_value, st_size = struct.unpack('<IBBHQQ', symdata[i:i+entsz])
                if st_name and st_value:
                    nm = zstr(strtab, st_name)
                    syms.setdefault(st_value, nm)
    return data, sections, syms

def read_cstr(data, sections, vaddr):
    for s in sections:
        if s['addr'] <= vaddr < s['addr'] + s['size'] and s['type'] != 8:
            off = s['offset'] + (vaddr - s['addr'])
            try:
                end = data.index(b'\x00', off)
            except ValueError:
                return None
            return data[off:end].decode('utf-8', 'replace')
    return None

def disasm_func(path, func_name=None, addr=None, size=None, show_xrefs_to=None):
    data, sections, syms = parse_elf(path)
    text = next(s for s in sections if s['name'] == '.text')
    md = Cs(CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN)
    md.detail = False
    code = data[text['offset']:text['offset']+text['size']]
    base = text['addr']
    if func_name:
        for a, n in syms.items():
            if n == func_name:
                addr = a
                break
        if addr is None:
            print(f"function {func_name} not found"); return
    if size is None:
        size = 0x4000
    start = addr - base
    insn_list = list(md.disasm(code[start:start+size], addr))
    # stop at first RET after at least a few insns when func requested
    out = []
    regs_adrp = {}
    for i, ins in enumerate(insn_list):
        comment = ''
        parts = ins.op_str
        if ins.mnemonic == 'adrp':
            try:
                rn, imm = parts.split(', ')
                regs_adrp[rn] = int(imm, 16)
            except Exception:
                pass
        elif ins.mnemonic == 'add' or ins.mnemonic == 'mov':
            ps = parts.split(', ')
            if len(ps) >= 3 and ps[1] in regs_adrp and ps[2].startswith('#'):
                va = regs_adrp[ps[1]] + int(ps[2][1:], 16)
                s = read_cstr(data, sections, va)
                if s is not None:
                    comment = f'  ; "{s[:120]}"'
                else:
                    if va in syms:
                        comment = f'  ; <{syms[va]}>'
        elif ins.mnemonic == 'bl':
            try:
                tgt = int(parts.lstrip('#'), 16)
                if tgt in syms:
                    comment = f'  ; <{syms[tgt]}>'
            except Exception:
                pass
        elif ins.mnemonic == 'adr':
            try:
                rn, imm = parts.split(', ')
                va = int(imm, 16)
                s = read_cstr(data, sections, va)
                if s is not None:
                    comment = f'  ; "{s[:120]}"'
            except Exception:
                pass
        out.append(f"{ins.address:08x}: {ins.mnemonic:10s} {ins.op_str}{comment}")
        if ins.mnemonic == 'ret' and func_name and i > 4:
            break
    print('\n'.join(out))

def list_funcs(path):
    data, sections, syms = parse_elf(path)
    text = next(s for s in sections if s['name'] == '.text')
    for a, n in sorted(syms.items()):
        if text['addr'] <= a < text['addr'] + text['size']:
            print(f"{a:08x}  {n}")

if __name__ == '__main__':
    path = sys.argv[1]
    if sys.argv[2] == 'funcs':
        list_funcs(path)
    else:
        name = sys.argv[2] if sys.argv[2] != 'none' else None
        addr = int(sys.argv[3], 16) if len(sys.argv) > 3 else None
        size = int(sys.argv[4], 16) if len(sys.argv) > 4 else None
        disasm_func(path, func_name=name, addr=addr, size=size)

